-- 2028 primary care visits by the patient's ATTRIBUTED practice: attribution = organization_id of the care_team_relationships row with role primary_care OR pediatric_primary_care and status 'assigned' (one per patient). Visits = distinct encounter_ids of type primary_care, office, pediatric_office or wellness dated 2028-01-01..2028-12-31 (versions de-duplicated), regardless of which site saw the patient.
WITH r AS MATERIALIZED (SELECT patient, stream, payload FROM records WHERE stream IN ('encounters','care_team_relationships')),
pcp AS (SELECT patient, json_extract(payload,'$.organization_id') practice FROM r WHERE stream='care_team_relationships' AND json_extract(payload,'$.role') IN ('primary_care','pediatric_primary_care') AND json_extract(payload,'$.status')='assigned'),
v AS (SELECT patient, json_extract(payload,'$.encounter_id') eid, min(json_extract(payload,'$.event_date')) d FROM r WHERE stream='encounters' AND json_extract(payload,'$.type') IN ('primary_care','office','pediatric_office','wellness') GROUP BY 1,2)
SELECT pcp.practice AS practice, COUNT(*) AS visits FROM v JOIN pcp USING(patient) WHERE v.d BETWEEN '2028-01-01' AND '2028-12-31' GROUP BY 1 ORDER BY 1;
